style.css:
@-moz-document domain("pinterest.com") {
/* 1. Forces the Plaid Image onto Pinterest's Main Containers */
    html, 
    body, 
    #app,
    #root,
    div[data-test-id="mainContainer"],
    div[data-test-id="grid"] {
        background-image: url("https://i.pinimg.com/1200x/b0/c3/ae/b0c3ae121fb1accb1c4b078df994ce5a.jpg") !important;
        background-color: transparent !important;
        background-repeat: repeat !important;
        background-size: 300px !important; /* Resize pattern scale here */
        background-attachment: fixed !important;
    }
    
    /* 2. Makes Feed Lists and Grid Columns Completely Transparent */
    div[data-test-id="feed-container"],
    div[data-test-id="pin-builder"],
    div[data-test-id="loaded-pin"],
    div[role="list"] {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 3. Frosted Glass Top Navigation Header */
    div[data-test-id="header"] {
        background: rgba(30, 24, 20, 0.85) !important;
        backdrop-filter: blur(12px) !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* 4. Keeps the Main Search Bar Visible & Readable */
    div[data-test-id="search-box-input"],
    form[name="search"] {
        background: rgba(255, 255, 255, 0.15) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
    }

    /* 5. Subtle Dark Border Shadow Around Pins so They Stand Out From Background */
    div[data-test-id="pin"],
    div[data-test-id="card"] {
        background: rgba(15, 12, 10, 0.4) !important;
        border-radius: 16px !important;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4) !important;
        padding: 4px !important;
    }

    /* 6. High-Contrast Text Adjustments for Titles and Descriptions */
    h1, h2, h3, div, span, p, a {
        color: #f7f5f2 !important;
    }
    
    /* Exception: Keep search bar text easily readable */
    input, textarea {
        color: #ffffff !important;
    }
}
